begin; select plan(6); select has_table('public','scalp_model_package','model package is persisted'); select has_function('graftvision_private','create_scalp_model_package',array['uuid','uuid','uuid','uuid'],'controlled package creation exists'); select has_function('graftvision_private','read_scalp_model_package',array['uuid','uuid','uuid'],'Doctor-safe projection exists'); select col_has_check('public','scalp_model_package','model_mode','model modes are bounded'); select is((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.scalp_model_package'::regclass),true,'forced RLS'); select is_empty('select * from information_schema.role_table_grants where table_schema=''public'' and table_name=''scalp_model_package'' and grantee in (''anon'',''authenticated'')','browser denied'); select * from finish(); rollback;
